import{z as o,x as s,o as t,c as n,q as i,j as r,D as E,d as e,s as A,S as l}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"致命三要素","description":"","frontmatter":{"title":"致命三要素","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deadly-triad.md","filePath":"llm/deadly-triad.md","lastUpdated":1791063341000}'),d={name:"llm/deadly-triad.md"};function p(c,a,m,D,_,F){const B=s("Mermaid");return t(),n("div",null,[a[2]||(a[2]=i('<h1 id="致命三要素" tabindex="-1">致命三要素 <a class="header-anchor" href="#致命三要素" aria-label="Permalink to &quot;致命三要素&quot;">​</a></h1><div class="epigraph"><p>函数逼近、自举、离策略，两两相安；三者聚齐，就把不动点赶出系统，值函数沿自己编的方向走远。</p><footer>—— 据 Sutton &amp; Barto, 2018, 第 11 章；Tsitsiklis &amp; Van Roy, 1997 整理</footer></div><p><a href="/llm/off-policy-importance-rl">上一课</a>校正了外来数据的分布差，但一切仍在表格里：每个状态一个槽。<a href="/llm/llm-decision-view">语言生成作为 MDP</a> 的维度灾难早已写明：LLM 的状态是前缀，槽写不下，值函数必须换成参数化的 \\(V_\\theta\\)、\\(Q_\\theta\\)，靠泛化活着。缺口：把函数逼近放进前几课的自举更新后，三个各自收敛保证完好的要素会互相点火。本课写致命三要素与 Tsitsiklis–Van Roy 的发散反例，以及深度 RLHF 为什么天天在线上走。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>表格账本先钉死：TD(0) 收敛（Sutton 1988），Q 学习收敛（Watkins &amp; Dayan 1992），三要素至多配齐两个。换成 \\(V_\\theta\\)，目标是 \\(r_{t+1}+\\gamma V_\\theta(s_{t+1})\\)——目标自己随参数动，半梯度法一步挪两次地面，不再是压缩映射的迭代。<span class="marginnote">「半梯度」指更新时只对当前状态的 \\(V_\\theta(s)\\) 求梯度，而把目标里的 \\(V_\\theta(s_{t+1})\\) 当成常数冻结——明知它也随参数在动，却假装不动。「一步挪两次地面」说的就是：你往目标走了一步，目标自己又挪了一步。</span>拆开看三要素各自的无害：函数逼近不配自举时只是回归，回归不发散；自举在表格里收敛；离策略在表格里也只是方差与覆盖问题（Q 学习）。合起来的失效链：泛化把一个状态的误差搬进一整片邻域，自举把这片误差设为别的状态的目标，离策略把「数据怎么来」与「目标希望谁被访问」脱钩——唯一依赖同策略访问分布的收敛证明随之失效。<span class="marginnote">术语翻译：自举（bootstrapping）直译「拽着自己的鞋带把自己拉起来」，指用自己当前的估计 \\(V_\\theta(s‘)\\) 去构造当前估计 \\(V_\\theta(s)\\) 的更新目标。单独看它很高效——不用等真实回报，走一步就更新；危险在于「拿没学准的估计当老师」，误差会顺着链条传下去。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分析工具是把更新过程写成算子。表格 TD 的更新是贝尔曼算子 \\(T\\) 与恒等的复合，\\(T\\) 在 \\(\\gamma\\lt1\\) 下是压缩映射，不动点存在且唯一；线性近似的半梯度 TD 是 \\(T\\) 与投影 \\(\\Pi\\) 的复合 \\(\\Pi T\\)，同策略数据下 \\(\\Pi T\\) 仍是平均压缩映射，Tsitsiklis–Van Roy 的收敛定理就是这一行。判据随之而来：检验一个配置是否安全，写出复合算子并看它的谱半径，越过 \\(1\\) 即发散——与步长无关，步长只改发散速度。<span class="marginnote">直觉类比：谱半径衡量「每轮更新把误差放大几倍」。把它想成滚雪球——系数 0.9 的坡上雪球越滚越小（收敛），系数 1.1 的坡上再小的雪球也越滚越大（发散），而且换多小的雪球出发都一样。「调小学习率」只是让雪球滚得慢，改不了坡度。</span>构造反例也用同一件工具：给两条转移、一个线性近似压不下的价值面，再让数据分布偏离同策略，Baird 的七状态星形就是这样搭出来的展品。</p><p>Tsitsiklis &amp; Van Roy 1997 给出这条链的精确形态：同策略、线性近似下，TD(0) 是投影算子与贝尔曼算子复合后的平均压缩映射，收敛；换成离策略数据，对应算子的谱半径可以越过 1，此时任何正步长都发散。反例小得省材料：论文中的两状态例子，线性近似、两条转移、数据来自另一个策略，参数在每步更新下振荡放大。Sutton &amp; Barto 第 11 章把 Baird 1995 的七状态反例记为标准展品：权重发散到无穷，与步长多小无关——收敛不是「慢」，是「没有」。</p>',9)),(t(),r(l,null,{default:E(()=>[A(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FA%5B%22%E5%87%BD%E6%95%B0%E9%80%BC%E8%BF%91%EF%BC%9A%E8%AF%AF%E5%B7%AE%E6%B3%9B%E5%8C%96%E6%88%90%E7%89%87%22%5D%20--%3E%20TOX%5B%22%E7%9B%AE%E6%A0%87%20r%20%2B%20%CE%B3V_%CE%B8(s%E2%80%B2)%20%E9%9A%8F%20%CE%B8%20%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20BOO%5B%22%E8%87%AA%E4%B8%BE%EF%BC%9A%E4%BC%B0%E8%AE%A1%E8%BF%9B%E4%BA%86%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20TOX%0A%20%20OFF%5B%22%E7%A6%BB%E7%AD%96%E7%95%A5%EF%BC%9A%E8%AE%BF%E9%97%AE%E5%88%86%E5%B8%83%E4%B8%8E%E7%9B%AE%E6%A0%87%E8%84%B1%E9%92%A9%22%5D%20--%3E%20TOX%0A%20%20TOX%20--%3E%20NOFP%5B%22%E5%8D%8A%E6%A2%AF%E5%BA%A6%E5%A4%B1%E5%8E%BB%E4%B8%8D%E5%8A%A8%E7%82%B9%E4%BF%9D%E8%AF%81%22%5D%0A%20%20NOFP%20--%3E%20DIV%5B%22%E8%B0%B1%E5%8D%8A%E5%BE%84%E8%B6%8A%E8%BF%87%201%EF%BC%9A%E5%8F%91%E6%95%A3%E6%88%96%E6%BC%82%E7%A7%BB%22%5D%0A%20%20NOFP%20--%3E%20MIT%5B%22%E7%BC%93%E8%A7%A3%EF%BC%9AKL%2Fclip%E3%80%81%E6%85%A2%20critic%E3%80%81%E5%88%A0%20critic%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p><span class="marginnote">Baird 1995 的反例：7 个状态、星形转移、线性近似，TD(0) 的部分权重在任意小步长下发散到无穷；Sutton &amp; Barto 2018 §11.2 以此为标准展品。「步长调小」治不了它。</span></p><p>深度 RLHF 的位置：PPO 一类做法是 actor-critic，critic 是 Transformer 上的价值头，每步回归自举目标（自举）；数据过不止一个 epoch 或来自异步 rollout（离策略）；价值头是深度网络（函数逼近）。三要素全占——深度 RLHF 的 critic 抖动是结构性的，不是事故，LLM 栏的 <a href="/llm/ac-stability">Actor-Critic 稳定性</a>从工程侧写过它。工程缓解都是拆掉或拉远某一要素：KL 正则与 clip 把策略拉住，让数据不离策略太远；价值头单独低学习率把自举放慢；<a href="/llm/grpo">GRPO</a> 干脆删掉 critic，用组内基线替换自举价值——用方差换掉发散风险。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>三要素的准确读法是「保证消失」，不是「必发散」：实践中多数时间不崩，崩起来不可预测且与步长无关，工程以稳定手段换回定理没覆盖的场景。发散的表现是谱系：数值爆炸、价值缓慢漂移、critic 永远追不上 actor，是同一结构病的不同进展速度。只占两要素的配置各有成熟账本：表格加离策略收敛（Q 学习），同策略的线性 TD 有收敛结果。</p>',4)),(t(),r(l,null,{default:E(()=>[A(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E5%87%BD%E6%95%B0%E9%80%BC%E8%BF%91%20%2B%20%E7%A6%BB%E7%AD%96%E7%95%A5%EF%BC%88%E6%97%A0%E8%87%AA%E4%B8%BE%EF%BC%89%22%5D%20--%3E%20S1%5B%22%E5%8F%AA%E6%98%AF%E5%9B%9E%E5%BD%92%20%2F%20%E7%9B%91%E7%9D%A3%E5%AD%A6%E4%B9%A0%EF%BC%8C%E4%B8%8D%E5%8F%91%E6%95%A3%22%5D%0A%20%20P2%5B%22%E8%87%AA%E4%B8%BE%20%2B%20%E7%A6%BB%E7%AD%96%E7%95%A5%EF%BC%88%E8%A1%A8%E6%A0%BC%EF%BC%89%22%5D%20--%3E%20S2%5B%22Q%20%E5%AD%A6%E4%B9%A0%E6%9C%89%E6%94%B6%E6%95%9B%E5%AE%9A%E7%90%86%22%5D%0A%20%20P3%5B%22%E5%87%BD%E6%95%B0%E9%80%BC%E8%BF%91%20%2B%20%E8%87%AA%E4%B8%BE%EF%BC%88%E5%90%8C%E7%AD%96%E7%95%A5%EF%BC%89%22%5D%20--%3E%20S3%5B%22%E7%BA%BF%E6%80%A7%20TD%EF%BC%9A%E5%B9%B3%E5%9D%87%E5%8E%8B%E7%BC%A9%E6%98%A0%E5%B0%84%EF%BC%8C%E6%94%B6%E6%95%9B%22%5D%0A%20%20ALL%5B%22%E4%B8%89%E8%80%85%E9%BD%90%22%5D%20--%3E%20S4%5B%22%E4%BF%9D%E8%AF%81%E6%B6%88%E5%A4%B1%EF%BC%9A%E8%B0%B1%E5%8D%8A%E5%BE%84%E5%8F%AF%E8%B6%8A%201%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">这张图回答「为什么叫三要素而不叫三宗罪」：任意两个凑一起都有现成的收敛证明兜底，唯独三个同时上场，定理集体失声。所以读 RLHF 实现时，可以拿这张表当体检单——数一数它占了几项，占满三项的 critic 就要靠 KL、慢学习率这类「拆要素」手段来续命。</span>奖励模型的过优化是另一条病——那是代理本身坏掉，与这里的学习动力学正交，见 <a href="/llm/rm-overoptimization">RM 过优化与 Goodhart</a>。下一课做实验：表格世界里三要素缺一，看不到发散，这份「安心」要带着条件收藏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>函数逼近、自举、离策略两两无害，三者合取使半梯度 TD 失去收敛保证。</li><li>Tsitsiklis &amp; Van Roy 1997：同策略是平均压缩映射；离策略时算子谱半径可越过 1。</li><li>反例极小：两状态线性即可发散；Baird 七状态的发散与步长无关。</li><li>RLHF 的 critic 三要素全占，抖动是结构性；KL、clip、慢 critic 与删 critic 都是在拆要素。</li><li>与奖励过优化正交：一个坏在学习动力学，一个坏在代理本身。</li><li>出处：Sutton &amp; Barto 2018 第 11 章；Tsitsiklis &amp; Van Roy 1997；Baird 1995。</li></ul>',3))])}const C=o(d,[["render",p]]);export{h as __pageData,C as default};
